create or replace function public.get_admin_home_tasks(p_cong_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$declare previous date=(date_trunc('month',now() at time zone 'Asia/Kolkata')-interval '1 month')::date;sy integer;mo integer;missing integer;draft jsonb;snapshot jsonb;unpublished integer;begin
if not public.ca_is_congregation_admin(p_cong_id) then raise exception 'Main administrator access required' using errcode='42501';end if;mo=extract(month from previous)::integer-1;sy=extract(year from previous)::integer+case when mo>=8 then 1 else 0 end;
select count(*) into missing from public.publishers p where p.cong_id=p_cong_id and not exists(select 1 from public.reports r where r.pub_id=p.id and r.cong_id=p_cong_id and r.service_year=sy and r.month=mo);
select data into draft from public.ca_oclm_workspaces where cong_id=p_cong_id;select p.snapshot into snapshot from public.ca_oclm_publications p where cong_id=p_cong_id;
select count(*) into unpublished from jsonb_each(coalesce(draft->'assignments','{}')) w where not coalesce(snapshot->'assignments','{}') ? w.key or exists(select 1 from jsonb_each(w.value) a where (case when coalesce(a.value->>'status','scheduled') in('cancelled','reassigned') then null else a.value->>'personId' end) is distinct from snapshot->'assignments'->w.key->a.key->>'personId' or coalesce(a.value->>'customTitle','') is distinct from coalesce(snapshot->'assignments'->w.key->a.key->>'customTitle',''));
return jsonb_build_object('reportsMissing',missing,'reportPeriod',to_char(previous,'FMMonth YYYY'),'unpublishedWeeks',unpublished,'attendance',ca_private.current_meeting(p_cong_id));end $$;
revoke all on function public.get_admin_home_tasks(text) from public,anon;grant execute on function public.get_admin_home_tasks(text) to authenticated;
